item.aggregated_output:
            continue
        content = item.get("content")
        if not isinstance(content, list):
            continue
        for block in content:
            if not isinstance(block, Mapping):
                continue
            text = block.get("text")
            if isinstance(text, str):
                parts.append(text)
    return "".join(parts)


def _decode_json_response(
    raw: bytes, headers: Mapping[str, Any]
) -> dict[str, Any]:
    charset = "utf-8"
    get_charset = getattr(headers, "get_content_charset", None)
    if callable(get_charset):
        charset = get_charset() or charset
    try:
        decoded = raw.decode(charset)
        data = json.loads(decoded)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise OpenAIClientError("OpenAI API returned invalid JSON") from exc
    if not isinstance(data, dict):
        raise OpenAIClientError("OpenAI API returned a non-object JSON response")
    return data


def _parse_error_body(exc: urllib.error.HTTPError) -> dict[str, Optional[str]]:
    try:
        raw = exc.read()
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return {}
    if not isinstance(data, dict):
        return {}
    error = data.get("error")
    if not isinstance(error, MutableMapping):
        return {}
    return {
        "type": _as_optional_str(error.get("type")),
        "code": _as_optional_str(error.get("code")),
        "message": _as_optional_str(error.get("message")),
    }


def _as_optional_str(value: Any) -> Optional[str]:
    return value if isinstance(value, str) else None


def _safe_reason(exc: BaseException) -> str:
    reason = getattr(exc, "reason", None)
    if reason is None:
        return exc.__class__.__name__
    return str(reason)


def _sleep_before_retry(attempt: int, headers: Optional[Mapping[str, Any]]) -> None:
    retry_after = _retry_after_seconds(headers)
    if retry_after is None:
        retry_after = min(8.0, 0.5 * (2**attempt)) + random.uniform(0, 0.25)
    time.sleep(retry_after)


def _retry_after_seconds(headers: Optional[Mapping[str, Any]]) -> Optional[float]:
    if not headers:
        return None
    raw = headers.get("Retry-After")
    if raw is None:
        return None
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return None
    return max(0.0, min(value, 30.0))


def _main(argv: Optional[list[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        description="Send a private prompt to OpenAI's Responses API via stdin."
    )
    parser.add_argument("--model", default=DEFAULT_MODEL)
    parser.add_argument("--max-output-tokens", type=int, default=None)
    parser.add_argument("--temperature", type=float, default=None)
    args = parser.parse_args(argv)

    prompt_text = sys.stdin.read()
    if not prompt_text:
        print("No prompt provided on stdin.", file=sys.stderr)
        return 2

    try:
        print(
            send_private_prompt(
                prompt_text,
                model=args.model,
                max_output_tokens=args.max_output_tokens,
                temperature=args.temperature,
            )
        )
    except OpenAIClientError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(_main())

